def are_numbers_ascending(s: str) -> bool:
    tokens = s.split()
    prev_num = -1    # By problem, all numbers are positive

    for token in tokens:
        if token.isdigit():
            curr_num = int(token)
            if curr_num <= prev_num:
                return False
            prev_num = curr_num

    return True
